<script type="text/javascript" >
jQuery(document).ready(function() {    
    jQuery("#actionperm").on( "click", function( e ) {
      //console.log( jQuery( this ).text() );
      e.preventDefault();
      var wf_transicion_id = jQuery("#wf_transicion_id option:selected").val();
      if(wf_transicion_id != 0){
        var pquery = "";
        if(jQuery("#wfactividadtransicion_id").val()){
            pquery = "&wfactividadtransicion_id=<?php echo $wf_actividad_transicion->getPrimaryKey(); ?>";
        }else{
            pquery = "&wf_flujo_id=<?php echo $wf_actividad_transicion->getWfFlujoId(); ?>";
        }
        var linked = "<?php echo $url_permisos; ?>" + wf_transicion_id + pquery;
        jQuery.OpenModalSIMAD(linked,'800','600');
      }else{
        alert("Debe seleccionar una acci�n a ejecutar!")
      }
    });
});

function updateJSON(element_id, data){
    var json = jQuery.parseJSON(data);    
    var $el = jQuery("#"+element_id);
    console.log(element_id);
    //************************************************************************
    $el.empty(); // remove old options
    $el.append(jQuery("<option></option>").attr("value", '0').text('Seleccione...'));
    // for each set of data, add a new option
    jQuery.each(jQuery(json),function(key,value){
        if(value.selected == true){
            $el.append(jQuery("<option></option>").attr("value", value.id).attr("selected", "selected").text(value.text));
        }else{
            $el.append(jQuery("<option></option>").attr("value", value.id).text(value.text));
        }
    });
}
</script>
                                    